import { emptySample, makeLand, type Land, type LandSample } from "./land";
import { makeWoodland, scatterChunk, type PlantChunk } from "./life";
import { smoothstep } from "./noise";
import { PLACE_CELL, placeCamp, placeInCell, type Camp, type Place } from "./places";
import { makeRegions, REGIONS, type RegionWeights } from "./regions";

/*
 * The endless world from its seed: the land and its water, the regions, camp,
 * and, generated by area as they are asked for, the places and the plants.
 * Everything is a pure function of the seed and a position, so any spot
 * always comes out the same however the world was walked to get there; what
 * has been worked out is kept a while, so asking again is cheap.
 */

export interface World {
  seed: string;
  camp: Camp;
  /** The land at a point, with camp and the places levelled into it. */
  sampleAt: (x: number, z: number, out?: LandSample) => LandSample;
  /** The land at a point as it lies, before camp and the places, sampled every `spacing` metres: for what is seen from too far off to show them. */
  landAt: (x: number, z: number, out?: LandSample, spacing?: number) => LandSample;
  heightAt: (x: number, z: number) => number;
  /** The water table at a point: water lies wherever it is above the ground. */
  waterAt: (x: number, z: number) => number;
  /** The top of whatever is there, ground or water. */
  surfaceAt: (x: number, z: number) => number;
  /** Which way a river flows at a point (a unit vector), or zero away from rivers. */
  flowAt: (x: number, z: number) => { x: number; z: number };
  regionAt: (x: number, z: number, land?: LandSample, out?: RegionWeights) => RegionWeights;
  /** How thick the woods grow at a point, 0 to 1, with clearings kept open unless `clearings` is false. */
  woodlandAt: (x: number, z: number, land: LandSample, weights: RegionWeights, slope: number, clearings?: boolean) => number;
  /** The wobble of the altitude bands at a point, in metres. */
  bandWobble: (x: number, z: number) => number;
  /** The place in a place cell, if it has one. */
  placeIn: (cellX: number, cellZ: number) => Place | null;
  /** Every place within `radius` metres of a point. */
  placesNear: (x: number, z: number, radius: number) => Place[];
  /** The plants of a plant chunk. */
  plantsIn: (chunkX: number, chunkZ: number) => PlantChunk;
}

/** How many places and plant chunks are kept once worked out. */
const KEPT_PLACES = 4096;
const KEPT_CHUNKS = 2048;

/** A map that forgets what was asked for longest ago once it holds `limit`. */
export function remembered<V>(limit: number, make: (key: string) => V): (key: string) => V {
  const kept = new Map<string, V>();
  return (key) => {
    const known = kept.get(key);
    if (known !== undefined) {
      kept.delete(key);
      kept.set(key, known);
      return known;
    }
    const value = make(key);
    kept.set(key, value);
    if (kept.size > limit) kept.delete(kept.keys().next().value as string);
    return value;
  };
}

function levelled(height: number, x: number, z: number, site: { x: number; z: number; y: number; flatten: number; blend: number }): number {
  if (site.flatten === 0) return height;
  const distance = Math.hypot(x - site.x, z - site.z);
  if (distance >= site.flatten + site.blend) return height;
  const t = distance <= site.flatten ? 1 : 1 - smoothstep(site.flatten, site.flatten + site.blend, distance);
  return height + (site.y - height) * t;
}

/** How wide a tarn's lip of moraine is, in metres. */
const TARN_LIP = 7;

/** A tarn's bowl: the ground cut down under its water, and raised into a lip round its shore so the water is held in. */
function tarn(height: number, x: number, z: number, cx: number, cz: number, pool: { level: number; radius: number }, out: LandSample): number {
  const d = Math.hypot(x - cx, z - cz);
  const { level, radius } = pool;
  if (d >= radius + TARN_LIP) return height;
  if (d < radius + 3) out.water = Math.max(out.water, level);
  if (d < radius) return Math.min(height, level - 0.3 - 2.6 * (1 - (d / radius) ** 2));
  return Math.max(height, level - 0.3 + 1.2 * Math.sin((Math.PI * (d - radius)) / TARN_LIP));
}

export function createWorld(seed: string): World {
  const land: Land = makeLand(seed);
  const regions = makeRegions(seed);
  const woods = makeWoodland(seed);
  const scratch = emptySample();
  const scratchWeights = new Float32Array(REGIONS.length);

  const rawWoodland = (x: number, z: number, s: LandSample) => woods.density(x, z, s, regions.weightsAt(x, z, s, scratchWeights), 0);
  const ground = { land, regions, woodland: rawWoodland };
  const camp = placeCamp(seed, ground);

  const placeOf = remembered(KEPT_PLACES, (key) => {
    const [cx, cz] = key.split(",").map(Number);
    return { place: placeInCell(seed, ground, cx, cz, camp) };
  });
  const placeIn = (cellX: number, cellZ: number) => placeOf(`${cellX},${cellZ}`).place;

  const sampleAt = (x: number, z: number, out: LandSample = emptySample()): LandSample => {
    land.sample(x, z, out);
    let h = levelled(out.height, x, z, camp);
    const place = placeIn(Math.floor(x / PLACE_CELL), Math.floor(z / PLACE_CELL));
    if (place) h = levelled(h, x, z, place);
    if (place?.pool) h = tarn(h, x, z, place.x, place.z, place.pool, out);
    out.height = h;
    return out;
  };

  /** 1 untouched, falling to 0 in the clearings round camp and the places. */
  const openness = (x: number, z: number): number => {
    let open = smoothstep(camp.clearing, camp.clearing + 8, Math.hypot(x - camp.x, z - camp.z));
    const place = placeIn(Math.floor(x / PLACE_CELL), Math.floor(z / PLACE_CELL));
    if (place) open *= smoothstep(place.clearing, place.clearing + 6, Math.hypot(x - place.x, z - place.z));
    return open;
  };

  const regionAt = (x: number, z: number, at?: LandSample, out?: RegionWeights) => regions.weightsAt(x, z, at ?? land.sample(x, z, scratch), out);
  const woodlandAt = (x: number, z: number, s: LandSample, weights: RegionWeights, slope: number, clearings = true) =>
    woods.density(x, z, s, weights, slope) * (clearings ? openness(x, z) : 1);

  const life = { seed, sampleAt, regionAt, openness, woodland: woods.density };
  const chunkOf = remembered(KEPT_CHUNKS, (key) => {
    const [cx, cz] = key.split(",").map(Number);
    return scatterChunk(life, cx, cz);
  });

  return {
    seed,
    camp,
    sampleAt,
    landAt: land.sample,
    heightAt: (x, z) => sampleAt(x, z, scratch).height,
    waterAt: (x, z) => sampleAt(x, z, scratch).water,
    surfaceAt: (x, z) => {
      const s = sampleAt(x, z, scratch);
      return Math.max(s.height, s.water);
    },
    flowAt: land.flowAt,
    regionAt,
    woodlandAt,
    bandWobble: woods.bandWobble,
    placeIn,
    placesNear(x, z, radius) {
      const out: Place[] = [];
      for (let cz = Math.floor((z - radius) / PLACE_CELL); cz <= Math.floor((z + radius) / PLACE_CELL); cz++) {
        for (let cx = Math.floor((x - radius) / PLACE_CELL); cx <= Math.floor((x + radius) / PLACE_CELL); cx++) {
          const place = placeIn(cx, cz);
          if (place && Math.hypot(place.x - x, place.z - z) <= radius) out.push(place);
        }
      }
      return out;
    },
    plantsIn: (chunkX, chunkZ) => chunkOf(`${chunkX},${chunkZ}`),
  };
}

